/**
 * Runtime module loader and glue code for weaver_wasm_adapter.
 * Generated by wasm-bindgen / Weaver Art build system.
 */

let wasm;

export class WasmWeavingEngine {
  constructor(shared_buffer) {
    if (!wasm) {
      throw new Error(
        "Módulo WebAssembly ('weaver_wasm_adapter') não foi inicializado. " +
          "Execute 'await init()' ou 'npm run build:wasm' para compilar o Wasm via wasm-pack."
      );
    }
    const ret = wasm.wasmweavingengine_new(shared_buffer);
    this.__wbg_ptr = ret;
  }

  free() {
    const ptr = this.__wbg_ptr;
    this.__wbg_ptr = 0;
    wasm.__wbg_wasmweavingengine_free(ptr);
  }

  load_and_prepare_image(raw_rgba, width, height, config_json) {
    return wasm.wasmweavingengine_load_and_prepare_image(this.__wbg_ptr, raw_rgba, width, height, config_json);
  }

  apply_user_importance_brush(brush_weights) {
    wasm.wasmweavingengine_apply_user_importance_brush(this.__wbg_ptr, brush_weights);
  }

  init_solver(config_json) {
    wasm.wasmweavingengine_init_solver(this.__wbg_ptr, config_json);
  }

  step_solver_batch(batch_size) {
    return wasm.wasmweavingengine_step_solver_batch(this.__wbg_ptr, batch_size) !== 0;
  }

  get_prepared_target_rgba() {
    return wasm.wasmweavingengine_get_prepared_target_rgba(this.__wbg_ptr);
  }

  get_importance_map_rgba() {
    return wasm.wasmweavingengine_get_importance_map_rgba(this.__wbg_ptr);
  }

  get_edges_rgba() {
    return wasm.wasmweavingengine_get_edges_rgba(this.__wbg_ptr);
  }

  get_radon_sinogram_rgba() {
    return wasm.wasmweavingengine_get_radon_sinogram_rgba(this.__wbg_ptr);
  }

  get_diagnostics_dimensions() {
    return wasm.wasmweavingengine_get_diagnostics_dimensions(this.__wbg_ptr);
  }

  generate_drilling_blueprint_svg() {
    return wasm.wasmweavingengine_generate_drilling_blueprint_svg(this.__wbg_ptr);
  }

  generate_drilling_blueprint_pdf() {
    return wasm.wasmweavingengine_generate_drilling_blueprint_pdf(this.__wbg_ptr);
  }

  generate_drilling_csv() {
    return wasm.wasmweavingengine_generate_drilling_csv(this.__wbg_ptr);
  }

  generate_cnc_gcode() {
    return wasm.wasmweavingengine_generate_cnc_gcode(this.__wbg_ptr);
  }

  generate_artwork_svg() {
    return wasm.wasmweavingengine_generate_artwork_svg(this.__wbg_ptr);
  }

  get_bom_summary_json() {
    return wasm.wasmweavingengine_get_bom_summary_json(this.__wbg_ptr);
  }
}

export default async function init(input) {
  if (wasm !== undefined) {
    return wasm;
  }

  if (typeof input === 'undefined') {
    try {
      input = new URL('weaver_wasm_adapter_bg.wasm', import.meta.url);
    } catch {
      // ignore
    }
  }

  let instance;
  try {
    if (input instanceof WebAssembly.Module) {
      instance = await WebAssembly.instantiate(input, {});
      wasm = instance.exports;
    } else if (input instanceof Response) {
      const res = await WebAssembly.instantiateStreaming(input, {});
      wasm = res.instance.exports;
    } else if (typeof input === 'string' || input instanceof URL) {
      const response = await fetch(input);
      const res = await WebAssembly.instantiateStreaming(response, {});
      wasm = res.instance.exports;
    } else if (input instanceof ArrayBuffer || ArrayBuffer.isView(input)) {
      const res = await WebAssembly.instantiate(input, {});
      wasm = res.instance.exports;
    } else {
      throw new Error(
        "Módulo WebAssembly ('weaver_wasm_adapter') não encontrado ou não compilado. " +
          "Execute 'npm run build:wasm' para compilar via wasm-pack."
      );
    }
  } catch (err) {
    throw new Error(
      "Falha ao carregar Wasm ('weaver_wasm_adapter'): " +
        (err instanceof Error ? err.message : String(err)) +
        ". Verifique se o módulo foi compilado com 'npm run build:wasm'."
    );
  }

  return wasm;
}
